window.LOGIC_BRICKS_SEARCH_INDEX=[{"title":"2D Actions","label":"Page","url":"actuators-2d.html","description":"46 actions available for 2D workflows."},{"title":"3D Actions","label":"Page","url":"actuators-3d.html","description":"58 actions available for 3D workflows."},{"title":"UI Actions","label":"Page","url":"actuators-ui.html","description":"21 actions available for UI workflows."},{"title":"Advanced","label":"Page","url":"advanced.html","description":"Larger-project guidance and automated tests."},{"title":"Brick Reference A-Z","label":"Page","url":"brick-reference.html","description":"A complete alphabetical index generated from the addon source."},{"title":"2D Gates","label":"Page","url":"controllers-2d.html","description":"2 gates available for 2D workflows."},{"title":"3D Gates","label":"Page","url":"controllers-3d.html","description":"2 gates available for 3D workflows."},{"title":"UI Gates","label":"Page","url":"controllers-ui.html","description":"2 gates available for UI workflows."},{"title":"Debugging","label":"Page","url":"debugging.html","description":"Use per-brick watches and the runtime debugger instead of temporary Print bricks."},{"title":"Your First Logic Chain","label":"Page","url":"first-chain.html","description":"Understand the core Trigger → Gate → Action workflow."},{"title":"Getting Started","label":"Page","url":"getting-started.html","description":"Install the addon and open the Logic Bricks editor."},{"title":"Graph Export","label":"Page","url":"graph-export.html","description":"Export organized Logic Bricks graphs as images for teaching and documentation."},{"title":"Learn Logic Bricks. Find answers quickly.","label":"Page","url":"index.html","description":"Professional documentation for the current Logic Bricks addon."},{"title":"Interface & Organization","label":"Page","url":"interface.html","description":"Menus, graph tools, side-panel data, templates, and frames."},{"title":"2D Triggers","label":"Page","url":"sensors-2d.html","description":"12 triggers available for 2D workflows."},{"title":"3D Triggers","label":"Page","url":"sensors-3d.html","description":"14 triggers available for 3D workflows."},{"title":"UI Triggers","label":"Page","url":"sensors-ui.html","description":"9 triggers available for UI workflows."},{"title":"Troubleshooting","label":"Page","url":"troubleshooting.html","description":"Resolve missing bricks, inactive chains, target errors, and processing warnings."},{"title":"Variables, States & Frames","label":"Page","url":"variables-states.html","description":"Store values, control active logic, and organize large graphs."},{"title":"Action Active","label":"3D Triggers","url":"sensors-3d.html#actuator-3d","description":"Fires TRUE when the named action on this node matches the chosen state. The action must have an instance name set."},{"title":"Always","label":"3D Triggers","url":"sensors-3d.html#always-common","description":"Always active trigger. Fires every frame. Useful for continuous actions like gravity or idle animations."},{"title":"Animation Tree","label":"3D Triggers","url":"sensors-3d.html#animation-tree-3d","description":"Detects animation tree state changes and conditions."},{"title":"Collision","label":"3D Triggers","url":"sensors-3d.html#collision-3d","description":"Detects collisions using this Area3D or an Area3D that is a direct child of the node using Logic Bricks."},{"title":"Compare Variable","label":"3D Triggers","url":"sensors-3d.html#compare-variable-common","description":"Compares a variable's value. Works with local, exported, and global variables. Automatically checks GlobalVars if not found locally."},{"title":"Delay","label":"3D Triggers","url":"sensors-3d.html#delay-common","description":"Waits for Delay seconds, then stays active for Duration seconds. Repeat cycles the whole sequence."},{"title":"Input","label":"3D Triggers","url":"sensors-3d.html#input-map-common","description":"Detects input actions from Project > Input Map. Supports button presses, any-action checks, and analog joystick axis input."},{"title":"Mouse","label":"3D Triggers","url":"sensors-3d.html#mouse-common","description":"Detects mouse buttons, wheel movement, mouse motion, and mouse hover ray hits."},{"title":"Movement Detected","label":"3D Triggers","url":"sensors-3d.html#movement-3d","description":"Detects if the node is moving in specific directions. Check which directions to monitor. Active when any checked direction moves past the threshold."},{"title":"Proximity","label":"3D Triggers","url":"sensors-3d.html#proximity-3d","description":"Detects objects within a distance and optional angle. Uses groups to filter which objects are detected."},{"title":"Random Chance","label":"3D Triggers","url":"sensors-3d.html#random-common","description":"Activates randomly each time it is evaluated. Pair with a Delay Trigger to control how often it rolls. Useful for random behaviors, AI variation, and loot rolls."},{"title":"Raycast Hit","label":"3D Triggers","url":"sensors-3d.html#raycast-3d","description":"Detects along a RayCast3D. This can be used for objects, groups, walls, ground, or ledges. The RayCast3D's direction, length, and collision mask are set on the RayCast3D node itself."},{"title":"Signal Receive","label":"3D Triggers","url":"sensors-3d.html#signal-common","description":"Detects signals sent by a Signal Send Action. Listens for a specific Signal name."},{"title":"Surface Check","label":"3D Triggers","url":"sensors-3d.html#physics-3d","description":"Checks CharacterBody3D collision state: on floor, on wall, on ceiling, or just landed. Use Landed for landing sounds, camera shake, particles, and other impact effects."},{"title":"Gate","label":"3D Gates","url":"controllers-3d.html#controller-controller-gd","description":"Logic gate that combines Trigger inputs. AND: all Triggers must be active. OR: any Trigger active. NAND/NOR/XOR: inverted and exclusive logic."},{"title":"Script Gate","label":"3D Gates","url":"controllers-3d.html#script-controller-script-controller-gd","description":"Calls a function in a custom .gd script when triggers fire. Runs a custom GDScript module function: no separate Action is needed — the script performs the action."},{"title":"Animation","label":"3D Actions","url":"actuators-3d.html#animation-3d","description":"Play, stop, or control animations by name. Automatically finds the AnimationPlayer that owns the animation. Works with AnimationPlayers nested at any depth."},{"title":"Animation State","label":"3D Actions","url":"actuators-3d.html#animation-state-3d","description":"Beginner-friendly AnimationTree control. Use Go To State for normal character animations. Blending comes from the transition Xfade Time inside the AnimationTree."},{"title":"Sprite3D Animation","label":"3D Actions","url":"actuators-3d.html#sprite-frames-3d","description":"Play, stop, or pause Sprite3D / AnimatedSprite3D frame animations. Finds the target by name anywhere in the scene tree. Leave Target Node empty to use the node this script is on."},{"title":"2D Audio","label":"3D Actions","url":"actuators-3d.html#2d-audio-3d","description":"Play 2D/UI audio from a file. Creates its own AudioStreamPlayer at runtime — no @export needed."},{"title":"3D Audio","label":"3D Actions","url":"actuators-3d.html#3d-audio-3d","description":"Plays audio with advanced options. Supports random pitch, audio buses, and multiple play modes."},{"title":"Music","label":"3D Actions","url":"actuators-3d.html#music-3d","description":"Three modes: Tracks: define and create music players at startup. Set: set which track is current (and optionally play it). Control: play, stop, pause, resume, or crossfade from current to another track."},{"title":"3rd Person Camera","label":"3D Actions","url":"actuators-3d.html#3rd-person-camera-3d","description":"Third-person camera setup: 1. Add a Node3D named CameraPivot near the character's head/shoulders. 2. Add a Camera3D and place it behind/above the pivot. 3. Choose both nodes with the dropdowns below."},{"title":"Camera Zoom","label":"3D Actions","url":"actuators-3d.html#camera-zoom-3d","description":"Changes a camera's FOV (3D) or zoom (2D). Choose the camera by name; it is found anywhere in the current scene."},{"title":"Set Camera","label":"3D Actions","url":"actuators-3d.html#set-camera-3d","description":"Makes a Camera3D anywhere in the edited scene active. Use the dropdown to choose the camera. A one-shot trigger is usually best so make_current() is not called every frame."},{"title":"Smooth Follow Camera","label":"3D Actions","url":"actuators-3d.html#smooth-follow-camera-3d","description":"Smoothly follows this node with the assigned Camera3D, maintaining the camera's initial offset from the target. Position follow: camera tracks the node's position per axis."},{"title":"Split Screen","label":"3D Actions","url":"actuators-3d.html#split-screen-3d","description":"Creates a split screen layout. Apply Code always builds all 4 SubViewportContainers. Each player count has its own independent layout. Change split_screen_players at runtime to switch counts without re-applying code."},{"title":"Light","label":"3D Actions","url":"actuators-3d.html#light-3d","description":"Control a light node's properties and apply animated FX effects. Leave Target Light blank to affect this node, or enter another light node name."},{"title":"World Environment","label":"3D Actions","url":"actuators-3d.html#environment-3d","description":"Modifies WorldEnvironment properties at runtime. Choose the WorldEnvironment by name; it is found anywhere in the current scene. All value fields accept a number or a variable name / expression."},{"title":"Game","label":"3D Actions","url":"actuators-3d.html#game-3d","description":"Game-level actions: quit, restart, or pause the game."},{"title":"Preload","label":"3D Actions","url":"actuators-3d.html#preload-3d","description":"Preloads resources (materials, scenes, textures, audio, meshes) into memory before they are needed, preventing runtime hitches and frame drops."},{"title":"Save / Load","label":"3D Actions","url":"actuators-3d.html#save-load-3d","description":"Saves or loads game state to/from a JSON file. Three scopes — no custom save()/load() methods needed on any node."},{"title":"Scene","label":"3D Actions","url":"actuators-3d.html#scene-3d","description":"Changes or manages scenes. Can switch to a new scene or reload the current one."},{"title":"Hit Stop","label":"3D Actions","url":"actuators-3d.html#hit-stop-3d","description":"Briefly pauses or slows game time when an impact lands. Use for attacks, damage, blocks, heavy landings, and breaks. This is also called hit pause or impact freeze."},{"title":"Object Flash","label":"3D Actions","url":"actuators-3d.html#object-flash-3d","description":"Flashes a mesh/object with a temporary color overlay. Type a node name, not a path. \"self\" also works on physics bodies by searching for a mesh child."},{"title":"Object Shake","label":"3D Actions","url":"actuators-3d.html#object-shake-3d","description":"Shakes a named object by rotation, translation, or scale, then returns it to its starting value. Type a node name, not a path. Use multiple Object Shake actions for multiple effects."},{"title":"Particles","label":"3D Actions","url":"actuators-3d.html#particles-3d","description":"Controls a GPUParticles or CPUParticles node in 2D or 3D."},{"title":"Rumble","label":"3D Actions","url":"actuators-3d.html#rumble-3d","description":"Trigger controller haptic vibration. Vibrate: manual motor control for a set duration. Stop: immediately stop all vibration. Pattern: built-in presets that play to completion."},{"title":"Screen Flash","label":"3D Actions","url":"actuators-3d.html#screen-flash-3d","description":"Flashes a color over the screen. Press \"Apply Code\" and the plugin creates the required nodes automatically. Works automatically in both standard and split-screen setups."},{"title":"Screen Shake","label":"3D Actions","url":"actuators-3d.html#screen-shake-3d","description":"Trauma-based camera shake. Type the Camera3D node name. The generated script searches the whole current scene tree, so this brick can live on any 3D node."},{"title":"Get Variable","label":"3D Actions","url":"actuators-3d.html#get-variable-3d","description":"Reads a variable/property from self, another node, or GlobalVars, then stores it as a local variable that later bricks can use. Useful for UI health bars, ammo labels, score text, and timers."},{"title":"Modify Variable","label":"3D Actions","url":"actuators-3d.html#modify-variable-3d","description":"Modifies a variable's value. Works with local and global variables. Automatically uses GlobalVars if not found locally."},{"title":"Random","label":"3D Actions","url":"actuators-3d.html#random-3d","description":"Sets a variable to a random value within a range. Useful for randomized behavior, damage variation, etc."},{"title":"Signal Send","label":"3D Actions","url":"actuators-3d.html#signal-3d","description":"Sends a named signal to other nodes. Receiving nodes need a Signal Receive Trigger with a matching Signal name."},{"title":"State","label":"3D Actions","url":"actuators-3d.html#state-3d","description":"Changes the logic brick state (1-30). Only chains assigned to the active state will run."},{"title":"Character Jump","label":"3D Actions","url":"actuators-3d.html#character-jump-3d","description":"Applies a jump impulse to a CharacterBody3D. Pair with any trigger — Input, Proximity, Message, etc. The Character Physics action handles gravity and resets the jump counter when grounded."},{"title":"Look At Input","label":"3D Actions","url":"actuators-3d.html#look-at-input-3d","description":"Rotates a Node3D to face the combined Input Map direction instead of the movement/slide direction. Named targets are searched across the current scene."},{"title":"Look At Movement","label":"3D Actions","url":"actuators-3d.html#look-at-movement-3d","description":"Rotates a child Node3D to face the direction of movement. The target is resolved only beneath this Logic Bricks node."},{"title":"Mouse","label":"3D Actions","url":"actuators-3d.html#mouse-3d","description":"Controls cursor visibility, mouse-look rotation, and mouse cursor world interactions."},{"title":"Path Follow","label":"3D Actions","url":"actuators-3d.html#waypoint-path-3d","description":"Moves this node through a series of waypoints or along an editable Path3D curve."},{"title":"Position","label":"3D Actions","url":"actuators-3d.html#position-3d","description":"Changes where a 3D object is. Use Character Velocity for CharacterBody3D movement, Translate for an offset, or Set Position for an exact location."},{"title":"Rotate Towards","label":"3D Actions","url":"actuators-3d.html#rotate-towards-3d","description":"Rotates this node to face a target found by name or group. Useful for turrets, enemies tracking a player, or any look-at behaviour."},{"title":"Rotation","label":"3D Actions","url":"actuators-3d.html#rotation-3d","description":"Rotates a 3D object. This action controls rotation only."},{"title":"Steering","label":"3D Actions","url":"actuators-3d.html#steering-3d","description":"Steers a node using reusable movement behaviors. Seek: move toward a target Flee: move away Arrive: slow as the target is reached Wander: move with changing randomized headings Maintain Distance: approach or retreat to…"},{"title":"Teleport","label":"3D Actions","url":"actuators-3d.html#teleport-3d","description":"Instantly sets position to a target node or coordinates. Useful for respawning, portals, checkpoints. Target Node mode finds the destination by name anywhere in the current scene."},{"title":"Edit Object","label":"3D Actions","url":"actuators-3d.html#edit-object-3d","description":"Add, remove, or replace objects in the scene at runtime. Useful for spawning enemies, projectiles, or swapping meshes."},{"title":"Get Transform","label":"3D Actions","url":"actuators-3d.html#get-transforms-3d","description":"Gets transform data from a Node2D or Node3D and stores each selected value as a variable for later bricks."},{"title":"Group","label":"3D Actions","url":"actuators-3d.html#group-3d","description":"Changes group membership at runtime. Works in both 2D and 3D. Leave Target Node blank to affect the node that owns these Logic Bricks."},{"title":"Node Properties","label":"3D Actions","url":"actuators-3d.html#property-3d","description":"Sets an Inspector property on Self or another node. The Property list updates to match the selected Target Node."},{"title":"Object Pool","label":"3D Actions","url":"actuators-3d.html#object-pool-3d","description":"Spawns objects from reusable pools. Faster than instancing — reuses inactive nodes. Pools are created at startup."},{"title":"Parent","label":"3D Actions","url":"actuators-3d.html#parent-3d","description":"Changes the node's parent in the scene tree. Useful for attaching objects to characters or vehicles."},{"title":"Set Transform","label":"3D Actions","url":"actuators-3d.html#set-transforms-3d","description":"Changes any combination of position, rotation, and scale on a Node2D or Node3D."},{"title":"Visibility","label":"3D Actions","url":"actuators-3d.html#visibility-3d","description":"Shows, hides, or toggles visibility of a node by name. Uses the same current-scene recursive name lookup as the Text Action."},{"title":"Character Physics","label":"3D Actions","url":"actuators-3d.html#character-physics-3d","description":"CharacterBody3D body rules: gravity, fall speed, floor snapping, slope limit, acceleration, friction, bounce, ground detection, and move_and_slide(). Horizontal speed is still controlled by movement Actions."},{"title":"Collision","label":"3D Actions","url":"actuators-3d.html#collision-3d","description":"Modifies collision properties at runtime. Can enable/disable shapes, change layers/masks, or toggle Area3D monitoring."},{"title":"Force","label":"3D Actions","url":"actuators-3d.html#force-3d","description":"Applies continuous central force to a RigidBody3D or SoftBody3D. On a SoftBody3D the force is distributed across all simulated points."},{"title":"Gravity","label":"3D Actions","url":"actuators-3d.html#gravity-3d","description":"Applies custom gravity to RigidBody3D or SoftBody3D. Soft bodies receive a central force while the brick is active."},{"title":"Impulse","label":"3D Actions","url":"actuators-3d.html#impulse-3d","description":"Applies a one-shot impulse. RigidBody3D supports Central, Positional, and Torque. SoftBody3D supports Central; use Soft Body Point Impulse for a specific mesh point."},{"title":"Linear Velocity","label":"3D Actions","url":"actuators-3d.html#linear-velocity-3d","description":"Sets, adds to, or averages the linear_velocity of a RigidBody3D. Requires a RigidBody3D node."},{"title":"Physics","label":"3D Actions","url":"actuators-3d.html#physics-3d","description":"Controls physics properties. Mass and Linear Damping support RigidBody3D and SoftBody3D; Soft Body actions expose native SoftBody3D properties."},{"title":"Soft Body Point Force","label":"3D Actions","url":"actuators-3d.html#soft-body-point-force-3d","description":"Applies continuous force to one SoftBody3D mesh point. Point indices refer to the soft body's simulated mesh points."},{"title":"Soft Body Point Impulse","label":"3D Actions","url":"actuators-3d.html#soft-body-point-impulse-3d","description":"Applies a one-shot impulse to one SoftBody3D mesh point. Use this for localized impacts and deformation."},{"title":"Surface Attachment","label":"3D Actions","url":"actuators-3d.html#surface-attachment-3d","description":"Attach to a physically touching surface, or detach. Supports rigid bodies and characters in 3D and 2D. Use a Collision or Surface Check trigger to choose when to attach."},{"title":"Torque","label":"3D Actions","url":"actuators-3d.html#torque-3d","description":"Applies a rotational force (torque) to a RigidBody3D each physics frame. Requires a RigidBody3D node."},{"title":"Always","label":"2D Triggers","url":"sensors-2d.html#always-common","description":"Always active trigger. Fires every frame. Useful for continuous actions like gravity or idle animations."},{"title":"Collision 2D","label":"2D Triggers","url":"sensors-2d.html#collision-2d-2d","description":"Detects collisions via an Area2D node. Leave Area Node Name blank when these Logic Bricks are attached directly to the Area2D. Otherwise, enter the node name (not the full path)."},{"title":"Compare Variable","label":"2D Triggers","url":"sensors-2d.html#compare-variable-common","description":"Compares a variable's value. Works with local, exported, and global variables. Automatically checks GlobalVars if not found locally."},{"title":"Delay","label":"2D Triggers","url":"sensors-2d.html#delay-common","description":"Waits for Delay seconds, then stays active for Duration seconds. Repeat cycles the whole sequence."},{"title":"Input","label":"2D Triggers","url":"sensors-2d.html#input-map-common","description":"Detects input actions from Project > Input Map. Supports button presses, any-action checks, and analog joystick axis input."},{"title":"Mouse","label":"2D Triggers","url":"sensors-2d.html#mouse-common","description":"Detects mouse buttons, wheel movement, mouse motion, and mouse hover ray hits."},{"title":"Movement Detected","label":"2D Triggers","url":"sensors-2d.html#movement-2d-2d","description":"Detects if a 2D node is moving in specific directions. Check which directions to monitor. Active when any checked direction moves past the threshold."},{"title":"Surface Check","label":"2D Triggers","url":"sensors-2d.html#physics-2d-2d","description":"Checks CharacterBody2D collision state: on floor, on wall, on ceiling, or just landed. Use Landed for landing sounds, camera shake, particles, and other impact effects."},{"title":"Proximity 2D","label":"2D Triggers","url":"sensors-2d.html#proximity-2d-2d","description":"Detects objects within a distance and optional angle. Uses groups to filter which objects are detected."},{"title":"Random Chance","label":"2D Triggers","url":"sensors-2d.html#random-common","description":"Activates randomly each time it is evaluated. Pair with a Delay Trigger to control how often it rolls. Useful for random behaviors, AI variation, and loot rolls."},{"title":"Raycast Hit 2D","label":"2D Triggers","url":"sensors-2d.html#raycast-2d-2d","description":"Detects along a RayCast2D. This can be used for objects, groups, walls, ground, or ledges. The RayCast2D's direction, length, and collision mask are set on the RayCast2D node itself."},{"title":"Signal Receive","label":"2D Triggers","url":"sensors-2d.html#signal-common","description":"Detects signals sent by a Signal Send Action. Listens for a specific Signal name."},{"title":"Gate","label":"2D Gates","url":"controllers-2d.html#controller-controller-gd","description":"Logic gate that combines Trigger inputs. AND: all Triggers must be active. OR: any Trigger active. NAND/NOR/XOR: inverted and exclusive logic."},{"title":"Script Gate","label":"2D Gates","url":"controllers-2d.html#script-controller-script-controller-gd","description":"Calls a function in a custom .gd script when triggers fire. Runs a custom GDScript module function: no separate Action is needed — the script performs the action."},{"title":"Sprite Animation","label":"2D Actions","url":"actuators-2d.html#sprite-animation-2d","description":"Play, stop, or pause AnimatedSprite2D animations. Leave Target Node empty to use the node this script is on."},{"title":"Tween","label":"2D Actions","url":"actuators-2d.html#tween-animation-2d","description":"Animates any property on self or on a node found by name anywhere in the current scene tree."},{"title":"2D Audio","label":"2D Actions","url":"actuators-2d.html#2d-audio-2d","description":"Play 2D/UI audio from a file. Creates its own AudioStreamPlayer at runtime — no @export needed."},{"title":"Music","label":"2D Actions","url":"actuators-2d.html#music-2d","description":"Three modes: Tracks: define and create music players at startup. Set: set which track is current (and optionally play it). Control: play, stop, pause, resume, or crossfade from current to another track."},{"title":"Camera Zoom","label":"2D Actions","url":"actuators-2d.html#camera-zoom-2d","description":"Changes Camera2D zoom. 1.0 = normal, 2.0 = zoomed in, 0.5 = zoomed out."},{"title":"Set Camera","label":"2D Actions","url":"actuators-2d.html#set-camera-2d","description":"Makes the named Camera2D the active camera. Use a one-shot trigger when possible so make_current() is not called every frame."},{"title":"Smooth Follow Camera","label":"2D Actions","url":"actuators-2d.html#smooth-follow-camera-2d","description":"Smoothly follows this Node2D with the named Camera2D while maintaining the camera's initial offset from the target."},{"title":"Split Screen","label":"2D Actions","url":"actuators-2d.html#split-screen-2d","description":"Configures a 2D split-screen layout using SubViewports and Camera2D nodes."},{"title":"Game","label":"2D Actions","url":"actuators-2d.html#game-2d","description":"Game-level actions: quit, restart, or pause the game."},{"title":"Preload","label":"2D Actions","url":"actuators-2d.html#preload-2d","description":"Preloads resources (materials, scenes, textures, audio, meshes) into memory before they are needed, preventing runtime hitches and frame drops."},{"title":"Save / Load","label":"2D Actions","url":"actuators-2d.html#save-load-2d","description":"Saves or restores 2D gameplay state for checkpoints and simple save systems."},{"title":"Scene","label":"2D Actions","url":"actuators-2d.html#scene-2d","description":"Changes or manages scenes. Can switch to a new scene or reload the current one."},{"title":"Camera Shake","label":"2D Actions","url":"actuators-2d.html#camera-shake-2d","description":"Shakes a Camera2D and returns it to its original offset and rotation."},{"title":"Hit Stop","label":"2D Actions","url":"actuators-2d.html#hit-stop-2d","description":"Briefly pauses or slows game time when an impact lands. Use for attacks, damage, blocks, heavy landings, and breaks. This is also called hit pause or impact freeze."},{"title":"Object Flash","label":"2D Actions","url":"actuators-2d.html#object-flash-2d","description":"Flashes a 2D object with a temporary color tint. Type a node name, not a path."},{"title":"Object Shake","label":"2D Actions","url":"actuators-2d.html#object-shake-2d","description":"Shakes a Node2D by position, rotation, or scale, then returns it to its starting transform."},{"title":"Particles","label":"2D Actions","url":"actuators-2d.html#particles-2d","description":"Controls a GPUParticles or CPUParticles node in 2D or 3D."},{"title":"Rumble","label":"2D Actions","url":"actuators-2d.html#rumble-2d","description":"Trigger controller haptic vibration. Vibrate: manual motor control for a set duration. Stop: immediately stop all vibration. Pattern: built-in presets that play to completion."},{"title":"Screen Flash","label":"2D Actions","url":"actuators-2d.html#screen-flash-2d","description":"Flashes a color over the screen. Press \"Apply Code\" and the plugin creates the required nodes automatically. Works automatically in both standard and split-screen setups."},{"title":"Get Variable","label":"2D Actions","url":"actuators-2d.html#get-variable-2d","description":"Reads a variable/property from self, another node, or GlobalVars, then stores it as a local variable that later bricks can use. Useful for UI health bars, ammo labels, score text, and timers."},{"title":"Modify Variable","label":"2D Actions","url":"actuators-2d.html#modify-variable-2d","description":"Modifies a variable's value. Works with local and global variables. Automatically uses GlobalVars if not found locally."},{"title":"Random","label":"2D Actions","url":"actuators-2d.html#random-2d","description":"Sets a variable to a random value within a range. Useful for randomized behavior, damage variation, etc."},{"title":"Signal Send","label":"2D Actions","url":"actuators-2d.html#signal-2d","description":"Sends a named signal to other nodes. Receiving nodes need a Signal Receive Trigger with a matching Signal name."},{"title":"State","label":"2D Actions","url":"actuators-2d.html#state-2d","description":"Changes the logic brick state (1-30). Only chains assigned to the active state will run."},{"title":"Character 2D Physics","label":"2D Actions","url":"actuators-2d.html#character-2d-physics-2d","description":"Applies reusable character physics to a CharacterBody2D. Pair with Position and Character Jump for player movement."},{"title":"Character Jump 2D","label":"2D Actions","url":"actuators-2d.html#character-jump-2d-2d","description":"Applies a jump to a CharacterBody2D. Pair with Character Physics for gravity and grounded behavior."},{"title":"Mouse","label":"2D Actions","url":"actuators-2d.html#mouse-2d","description":"Uses the mouse for 2D cursor visibility, aiming, rotation, and move-toward behavior."},{"title":"Path Follow","label":"2D Actions","url":"actuators-2d.html#waypoint-path-2d","description":"Moves this node through editable Node2D waypoint points or along a Path2D curve."},{"title":"Position 2D","label":"2D Actions","url":"actuators-2d.html#position-2d","description":"Changes where a 2D object is. Use Character Velocity for CharacterBody2D movement, Translate for an offset, or Set Position for an exact location."},{"title":"Rotate Towards","label":"2D Actions","url":"actuators-2d.html#rotate-towards-2d","description":"Turns a Node2D toward another node or the nearest member of a group."},{"title":"Rotation 2D","label":"2D Actions","url":"actuators-2d.html#rotation-2d","description":"Rotates a 2D object by a number of degrees."},{"title":"Scale 2D","label":"2D Actions","url":"actuators-2d.html#scale-2d","description":"Changes only the scale of a 2D object. Enable Tween to animate to the target scale."},{"title":"Steering","label":"2D Actions","url":"actuators-2d.html#steering-2d","description":"Steers a Node2D with Seek, Flee, Arrive, Wander, Maintain Distance, or Orbit behaviors."},{"title":"Teleport 2D","label":"2D Actions","url":"actuators-2d.html#teleport-2d-2d","description":"Instantly sets position to a target Node2D or coordinates. Useful for respawning, portals, checkpoints, and spawn points."},{"title":"Get Transform","label":"2D Actions","url":"actuators-2d.html#get-transforms-2d","description":"Gets transform data from a Node2D or Node3D and stores each selected value as a variable for later bricks."},{"title":"Group","label":"2D Actions","url":"actuators-2d.html#group-2d","description":"Changes group membership at runtime. Works in both 2D and 3D. Leave Target Node blank to affect the node that owns these Logic Bricks."},{"title":"Node Properties","label":"2D Actions","url":"actuators-2d.html#property-2d","description":"Sets an Inspector property on Self or another node. The Property list updates to match the selected Target Node."},{"title":"Parent","label":"2D Actions","url":"actuators-2d.html#parent-2d","description":"Parents this 2D node to another scene node or the first node in a group, or removes its current parent."},{"title":"Set Transform","label":"2D Actions","url":"actuators-2d.html#set-transforms-2d","description":"Changes any combination of position, rotation, and scale on a Node2D or Node3D."},{"title":"Visibility","label":"2D Actions","url":"actuators-2d.html#visibility-2d","description":"Shows, hides, or toggles visibility of a node by name. Uses the same current-scene recursive name lookup as the Text Action."},{"title":"Collisions","label":"2D Actions","url":"actuators-2d.html#collisions-2d","description":"Enables, disables, or edits 2D collision settings on a target node."},{"title":"Force","label":"2D Actions","url":"actuators-2d.html#force-2d-2d","description":"Applies continuous force to a RigidBody2D. X/Y fields accept numbers, variables, or expressions."},{"title":"Gravity","label":"2D Actions","url":"actuators-2d.html#gravity-2d","description":"Sets persistent directional gravity on a RigidBody2D."},{"title":"Impulse 2D","label":"2D Actions","url":"actuators-2d.html#impulse-2d-2d","description":"Applies an instant push to a RigidBody2D. Use Force when the push should continue over time."},{"title":"Linear Velocity 2D","label":"2D Actions","url":"actuators-2d.html#linear-velocity-2d-2d","description":"Directly sets velocity on a RigidBody2D or CharacterBody2D."},{"title":"Surface Attachment","label":"2D Actions","url":"actuators-2d.html#surface-attachment-2d","description":"Attach to a physically touching surface, or detach. Supports rigid bodies and characters in 3D and 2D. Use a Collision or Surface Check trigger to choose when to attach."},{"title":"Always","label":"UI Triggers","url":"sensors-ui.html#always-ui","description":"Runs continuously while this logic chain is active. Useful for UI updates that need to happen every frame."},{"title":"Button","label":"UI Triggers","url":"sensors-ui.html#button-ui","description":"Detects UI button state from a Button node. Leave Target Node Name blank to use self only when this Logic Bricks graph is on the Button itself."},{"title":"Compare Variable","label":"UI Triggers","url":"sensors-ui.html#compare-variable-ui","description":"Compares a variable's value. Works with local, exported, and global variables. Automatically checks GlobalVars if not found locally."},{"title":"Delay","label":"UI Triggers","url":"sensors-ui.html#delay-ui","description":"Waits for Delay seconds, then stays active for Duration seconds. Repeat cycles the whole sequence."},{"title":"Input","label":"UI Triggers","url":"sensors-ui.html#input-map-ui","description":"Detects input actions from Project > Input Map. Supports button presses, any-action checks, and analog joystick axis input."},{"title":"Mouse","label":"UI Triggers","url":"sensors-ui.html#mouse-ui","description":"Detects mouse buttons, wheel movement, mouse motion, and mouse hover ray hits."},{"title":"Random Chance","label":"UI Triggers","url":"sensors-ui.html#random-ui","description":"Activates randomly each time it is evaluated. Pair with a Delay Trigger to control how often it rolls. Useful for random behaviors, AI variation, and loot rolls."},{"title":"Signal Receive","label":"UI Triggers","url":"sensors-ui.html#signal-ui","description":"Detects signals sent by a Signal Send Action. Listens for a specific Signal name."},{"title":"Variable","label":"UI Triggers","url":"sensors-ui.html#variable-ui","description":"Compares a variable's value. Works with local, exported, and global variables. Automatically checks GlobalVars if not found locally."},{"title":"Gate","label":"UI Gates","url":"controllers-ui.html#controller-controller-gd","description":"Logic gate that combines Trigger inputs. AND: all Triggers must be active. OR: any Trigger active. NAND/NOR/XOR: inverted and exclusive logic."},{"title":"Script Gate","label":"UI Gates","url":"controllers-ui.html#script-controller-script-controller-gd","description":"Calls a function in a custom .gd script when triggers fire. Runs a custom GDScript module function: no separate Action is needed — the script performs the action."},{"title":"2D Audio","label":"UI Actions","url":"actuators-ui.html#2d-audio-ui","description":"Play 2D/UI audio from a file. Creates its own AudioStreamPlayer at runtime — no @export needed."},{"title":"Animation","label":"UI Actions","url":"actuators-ui.html#animation-ui","description":"Play, stop, or control animations by name. Automatically finds the AnimationPlayer that owns the animation. Works with AnimationPlayers nested at any depth."},{"title":"Button","label":"UI Actions","url":"actuators-ui.html#button-ui","description":"Controls a BaseButton such as Button, CheckBox, or TextureButton."},{"title":"Color / Transparency","label":"UI Actions","url":"actuators-ui.html#modulate-ui","description":"Sets or smoothly transitions the color/alpha of a UI or 2D node found by name anywhere in the current scene tree."},{"title":"Focus","label":"UI Actions","url":"actuators-ui.html#focus-ui","description":"Grabs or releases UI focus on a Control node."},{"title":"Get Variable","label":"UI Actions","url":"actuators-ui.html#get-variable-ui","description":"Reads a variable/property from self, another node, or GlobalVars, then stores it as a local variable that later bricks can use. Useful for UI health bars, ammo labels, score text, and timers."},{"title":"Modify Variable","label":"UI Actions","url":"actuators-ui.html#modify-variable-ui","description":"Modifies a variable's value. Works with local and global variables. Automatically uses GlobalVars if not found locally."},{"title":"Music","label":"UI Actions","url":"actuators-ui.html#music-ui","description":"Three modes: Tracks: define and create music players at startup. Set: set which track is current (and optionally play it). Control: play, stop, pause, resume, or crossfade from current to another track."},{"title":"Node Properties","label":"UI Actions","url":"actuators-ui.html#property-ui","description":"Sets an Inspector property on Self or another node. The Property list updates to match the selected Target Node."},{"title":"Popup","label":"UI Actions","url":"actuators-ui.html#popup-ui","description":"Controls a Popup, PopupPanel, AcceptDialog, Window, or visible Control."},{"title":"Progress Bar","label":"UI Actions","url":"actuators-ui.html#progress-bar-ui","description":"Sets the value, min, or max of a ProgressBar, HSlider, VSlider, or any Range node found by name anywhere in the current scene tree."},{"title":"Screen Flash","label":"UI Actions","url":"actuators-ui.html#screen-flash-ui","description":"Flashes a color over the screen. Press \"Apply Code\" and the plugin creates the required nodes automatically. Works automatically in both standard and split-screen setups."},{"title":"Scroll","label":"UI Actions","url":"actuators-ui.html#scroll-ui","description":"Moves a ScrollContainer by setting or adding to its scroll position."},{"title":"Signal Send","label":"UI Actions","url":"actuators-ui.html#signal-ui","description":"Sends a named signal to other nodes. Receiving nodes need a Signal Receive Trigger with a matching Signal name."},{"title":"Slider","label":"UI Actions","url":"actuators-ui.html#slider-ui","description":"Changes the value of HSlider, VSlider, ProgressBar, SpinBox, or another Range node."},{"title":"State","label":"UI Actions","url":"actuators-ui.html#state-ui","description":"Changes the logic brick state (1-30). Only chains assigned to the active state will run."},{"title":"Tab","label":"UI Actions","url":"actuators-ui.html#tab-ui","description":"Sets, advances, or reverses the active TabContainer tab."},{"title":"Text","label":"UI Actions","url":"actuators-ui.html#text-ui","description":"Updates a Label, Label3D, or RichTextLabel by node name. Searches the whole current scene tree, so this brick can live on any node."},{"title":"Tween","label":"UI Actions","url":"actuators-ui.html#tween-ui","description":"Animates any property on self or on a node found by name anywhere in the current scene tree."},{"title":"Visibility","label":"UI Actions","url":"actuators-ui.html#visibility-ui","description":"Shows, hides, or toggles visibility of a node by name. Uses the same current-scene recursive name lookup as the Text Action."},{"title":"Window","label":"UI Actions","url":"actuators-ui.html#window-ui","description":"Controls a Godot Window node, such as a settings or dialog window."},{"title":"Apply Code","label":"Interface","url":"interface.html#apply-code","description":"Version stamp, graph backup, and the project settings Apply Code turns on."},{"title":"Graph backup","label":"Interface","url":"interface.html#graph-backup","description":"Restore lost bricks from the backup saved in the generated script."},{"title":"Sync Bricks from Script","label":"Interface","url":"interface.html#graph-backup","description":"Bring code edits back into the bricks or restore a lost graph."},{"title":"Renaming nodes","label":"Interface","url":"interface.html#renaming-nodes","description":"Bricks follow nodes renamed in the Scene dock."},{"title":"Updating the add-on","label":"Interface","url":"interface.html#updating","description":"Reload Logic Bricks, Apply Code, and Find Outdated Scripts after an update."},{"title":"Find Outdated Scripts","label":"Interface","url":"interface.html#updating","description":"List scripts generated by a different Logic Bricks version."},{"title":"Reload Logic Bricks","label":"Interface","url":"interface.html#updating","description":"Project → Tools → Reload Logic Bricks after replacing the add-on."},{"title":"Automated tests","label":"Advanced","url":"advanced.html#automated-tests","description":"Run the add-on's test suite in the editor or from a terminal."},{"title":"Avoid Walls","label":"3rd Person Camera","url":"actuators-3d.html#3rd-person-camera-3d","description":"Keep the 3rd person camera in front of walls; look past pillars and posts."},{"title":"Physics interpolation","label":"Troubleshooting","url":"troubleshooting.html#camera-stutter","description":"Smooth mouse look and camera movement between physics ticks."},{"title":"Errors after updating","label":"Troubleshooting","url":"troubleshooting.html#after-updating","description":"Fix 'Nonexistent function … in base Nil' after replacing the add-on."}];
